'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{spawn}=require('node:child_process');
const I=require('./index.cjs'),B=require('./cleanup-backend.cjs'),S=require('./cleanup-schema.cjs'),F=require('./fixtures.cjs'),R=require('./recovery-fixtures.cjs');
const root=process.env.PUBLIC_TEST_TMP_ROOT||process.env.RUNNER_TEMP,python=process.env.PUBLIC_TEST_PYTHON;assert(root&&python);
async function control(failure){
 const directory=fs.mkdtempSync(path.join(root,'recovery-pipe-')),f=R.incomplete(F.fixture(directory,{mode:'terminal',reconcile:true}));const source=await B.readTarget(f.c,f.deps);fs.writeFileSync(path.join(directory,'public-witness.json'),S.canonical(R.witness(source)));const env={...F.env(f.c),RUNNER_TEMP:directory,PUBLIC_FIXTURE_ROOT:directory,GH_TOKEN:'PUBLIC_MANAGER_NONAUTH',ACTIONS_RUNTIME_TOKEN:'PUBLIC_ARTIFACT_NONAUTH',ACTIONS_RESULTS_URL:'https://public.invalid/',GITHUB_TOKEN:'PUBLIC_TOKEN_NONAUTH'};for(const k of ['PATH','HOME','TMPDIR'])if(process.env[k])env[k]=process.env[k];let starts=0;const calls=[];
 const worker=async pack=>{calls.push(pack.request.command);let out;if(pack.request.command==='READ_TARGET')out=await B.readTarget(pack.context,f.deps);else if(pack.request.command==='DERIVE')out=await B.admitDerived(pack.context,pack.bundle,pack.request.payload,f.deps);else if(pack.request.command==='HISTORY')out=await B.handlerHistory(pack.context,pack.bundle,pack.current_records,f.deps);else out=await B.persist(pack.request.payload,pack.context,pack.bundle,pack.current_records,f.deps);if(failure===pack.request.command||(failure==='UNKNOWN'&&pack.request.command==='PERSIST'&&pack.request.payload.phase==='UNKNOWN'))throw new Error('PUBLIC_ACK_LOSS_NO_SECRET');return out;};
 const spawnChild=(exe,args,options)=>{starts++;assert.deepEqual(args,['-I','-m','just_akash.scanner_v2_recovery_cleanup']);const sourceRoot=path.resolve(__dirname,'../../..'),fixture=path.join(__dirname,'tests/fixture_controller.py');return spawn(exe,['-I','-c',`import sys,runpy;sys.path.insert(0,${JSON.stringify(sourceRoot)});runpy.run_path(${JSON.stringify(fixture)},run_name='__main__')`],options);};
 let accepted=false;try{await I.supervise({python,env,worker,spawnChild});accepted=true;}catch{}fs.writeFileSync(path.join(directory,'public-pipe-observation.json'),S.canonical({calls,starts,accepted}));return {directory,f,calls,starts,accepted};
}
test('real Python pipe and Node supervisor require derivation readback then both intents/UNKNOWN before sentinel',async()=>{const x=await control();assert(x.accepted);assert.equal(x.starts,1);assert.equal(fs.readFileSync(path.join(x.directory,'synthetic-effect.txt'),'utf8'),'ONE_PUBLIC_SENTINEL_NO_NETWORK\n');assert.deepEqual(x.calls,['READ_TARGET','DERIVE','PERSIST','PERSIST','PERSIST','HISTORY','PERSIST']);});
for(const failure of ['DERIVE','UNKNOWN'])test('lost '+failure+' ACK poisons actual pipe before sentinel, no second child',async()=>{const x=await control(failure);assert.equal(x.accepted,false);assert.equal(x.starts,1);assert(!fs.existsSync(path.join(x.directory,'synthetic-effect.txt')));assert.equal(x.calls.filter(c=>c==='DERIVE').length,1);});
test('new worker excludes management/Console/AGE while fixed child excludes artifact runtime',()=>{const e={GH_TOKEN:'PUBLIC_MANAGER',AKASH_API_KEY:'PUBLIC_CONSOLE',SOPS_AGE_KEY:'PUBLIC_AGE',ACTIONS_RUNTIME_TOKEN:'PUBLIC_ARTIFACT',ACTIONS_RESULTS_URL:'https://public.invalid/',GITHUB_TOKEN:'PUBLIC_TOKEN','INPUT_GITHUB-TOKEN':'PUBLIC_READER',NODE_OPTIONS:'--bad',RUNNER_TEMP:root};const worker=I.workerEnvironment(e);assert(!Object.values(worker).some(x=>['PUBLIC_MANAGER','PUBLIC_CONSOLE','PUBLIC_AGE'].includes(x)));const child=I.childEnvironment(e,F.current('terminal').actor);assert.equal(child.GH_TOKEN,'PUBLIC_MANAGER');assert(!Object.keys(child).some(k=>k.startsWith('ACTIONS_')||k.startsWith('INPUT_')));assert(!Object.hasOwn(child,'GITHUB_TOKEN'));assert.equal(I.PHASE_MS,18000);assert.equal(I.MAX_COMMANDS,64);assert.equal(I.MAX_PHASES,32);});
